const incoming = $json.body ?? $json;
const nestedPayload = incoming.payload && typeof incoming.payload === 'object' ? incoming.payload : {};
const normalized = {...nestedPayload, ...incoming};
normalized.payload = nestedPayload.payload ?? nestedPayload;
normalized.mode = normalized.mode || 'dry_run';
normalized.action = normalized.action || 'run_lifecycle';
normalized.tool_results = Array.isArray(normalized.tool_results) ? normalized.tool_results : [];
normalized.desired_tools = Array.isArray(normalized.desired_tools) ? normalized.desired_tools : null;
delete normalized.skipped_tool;
const toolName = 'tool_qa_delivery';
const shouldRun = !normalized.desired_tools || normalized.desired_tools.includes(toolName);
if (!shouldRun) {
  const results = [...normalized.tool_results, {tool: toolName, status: 'skipped', reason: 'not selected for action'}];
  return [{json: {...normalized, tool_results: results, skipped_tool: toolName}}];
}
const llmRequestBodyJson = JSON.stringify({model:(normalized.llm_model || 'gpt-4o-mini'), messages:[{role:'system',content:'QA outputs. Flag unsupported claims and missing information. Return strict JSON.'},{role:'user',content:JSON.stringify(normalized)}], response_format:{type:'json_object'}});
return [{json: {...normalized, current_stage: toolName, live_mode: normalized.mode === 'live', llm_request_body_json: llmRequestBodyJson}}];

const output = {...$json};
delete output.skipped_tool;
return [{json: output}];

const state = $node['Normalize And Auth'].json;
if (state.skipped_tool) {
  return [{json: state}];
}
const rawText = $json.message?.content ?? $json.choices?.[0]?.message?.content ?? $json.body?.choices?.[0]?.message?.content ?? $json.data?.choices?.[0]?.message?.content ?? '';
const cleanedRawText = typeof rawText === 'string' ? rawText.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '') : rawText;
let parsed;
let parseWarning = false;
let warningMessage = '';
if (state.mode === 'dry_run' && !rawText) {
  parsed = state.fallback_payload || state.qa_report || {
    job_id: state.job_id,
    overall_status: 'pass',
    checks: [{name: 'dry_run_qa', status: 'pass', notes: 'Dry-run fallback QA passed.'}],
    issues: [],
    required_revisions: []
  };
} else {
  try {
    parsed = typeof cleanedRawText === 'string' ? JSON.parse(cleanedRawText) : cleanedRawText;
  } catch (error) {
    parseWarning = true;
    warningMessage = error.message;
    parsed = {
      job_id: state.job_id,
      overall_status: 'review_required',
      checks: [{name: 'parse', status: 'warning', notes: error.message}],
      issues: [{issue_code: 'qa_parse_warning', severity: 'medium', repairable: false, repair_type: 'human_review', message: error.message}],
      required_revisions: ['Review unparseable QA response.'],
      raw_text: rawText,
      parse_warning: true
    };
  }
}
parsed.job_id = parsed.job_id || state.job_id;
parsed.checks = Array.isArray(parsed.checks) ? parsed.checks : [];
parsed.issues = Array.isArray(parsed.issues) ? parsed.issues.map((issue, index) => ({
  issue_code: String(issue.issue_code || issue.code || ('qa_issue_' + (index + 1))),
  severity: String(issue.severity || 'medium'),
  repairable: issue.repairable === true,
  repair_type: String(issue.repair_type || (issue.repairable === true ? 'safe_content_repair' : 'human_review')),
  output_type: issue.output_type || '',
  message: String(issue.message || issue.notes || issue.description || 'QA issue')
})) : [];
parsed.required_revisions = Array.isArray(parsed.required_revisions) ? parsed.required_revisions : [];
const issueCount = parsed.issues.length;
const repairableIssueCount = parsed.issues.filter(issue => issue.repairable).length;
const blockingIssueCount = parsed.issues.filter(issue => !issue.repairable).length;
if (!parsed.overall_status) {
  parsed.overall_status = blockingIssueCount > 0 ? 'review_required' : (repairableIssueCount > 0 ? 'repairable_issues' : 'pass');
}
parsed.repair_summary = {
  issue_count: issueCount,
  repairable_issue_count: repairableIssueCount,
  blocking_issue_count: blockingIssueCount,
  max_repair_attempts: Number(state.max_repair_attempts || parsed.max_repair_attempts || 2)
};
const outputJson = JSON.stringify(parsed || {});
const outputJsonB64 = Buffer.from(outputJson, 'utf8').toString('base64');
const safeSql = value => String(value ?? '').replace(/'/g, "''");
return [{json: {...state, qa_report: parsed, qa_report_json: outputJson, qa_report_json_b64: outputJsonB64, qa_report_json_sql: safeSql(outputJson), raw_model_text: rawText, raw_model_text_sql: safeSql(rawText), parse_warning: parseWarning, warning_message: warningMessage, warning_message_sql: safeSql(warningMessage), current_stage_sql: safeSql(state.current_stage), output_type_sql: safeSql(state.output_type), dispatch_label_sql: safeSql(state.dispatch_label), qa_status: 'pending'}}];

const base = $node['Normalize And Auth'].json;
const current = $json;
const status = current.status || 'waiting_for_human_review';
const results = [...(base.tool_results || []), {tool: 'tool_qa_delivery', status, job_id: current.job_id || base.job_id || ''}];
return [{json: {...base, ...current, job_id: current.job_id || base.job_id, status, tool_results: results, current_stage: 'tool_qa_delivery'}}];

const base = $node['Normalize And Auth'].json;
const results = [...(base.tool_results || []), {tool: 'tool_qa_delivery', status: 'waiting_for_human_review', reason: 'final human approval is required before delivery pack'}];
return [{json: {...base, status: 'waiting_for_human_review', gate_blocked: true, gate_reason: 'final human approval is required before delivery pack', tool_results: results}}];
